-- users: company employees. Accounts are created in advance by an admin;
-- there is no self sign-up. The first admin is created at startup from
-- INITIAL_ADMIN_EMAIL. Email is the only way to sign in.
-- id:         Sonyflake id generated by the app, e.g. 587364927401230337
-- email:      always lowercase, e.g. 'ali@example.com'
-- name:       e.g. 'Ali Valiyev'
-- role:       the user's only role; its permissions go into the access token, e.g. 'admin'
-- enabled:    e.g. false = cannot sign in, all sessions are ended
-- created_at: e.g. '2026-10-15 09:00:00+05'
-- updated_at: e.g. NULL until the first change
CREATE TABLE users (
    id         BIGINT      PRIMARY KEY,
    email      TEXT        NOT NULL UNIQUE CHECK (email = lower(email)),
    name       TEXT        NOT NULL,
    role       TEXT        NOT NULL DEFAULT 'user' REFERENCES roles (key) ON DELETE RESTRICT,
    enabled    BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ
);

-- Which users have a role; also checked when a role is deleted.
CREATE INDEX users_role_idx ON users (role);
